### What are the core entities?

The core entities are `VendingMachine`, `MachineState`, concrete state classes, `Product`, and `Slot`.

```java
package com.bank.vending.model;

import java.math.BigDecimal;

public class Product {
    private final String name;
    private final BigDecimal price;

    public Product(String name, BigDecimal price) {
        this.name = name;
        this.price = price;
    }

    public String getName() { return name; }
    public BigDecimal getPrice() { return price; }
}
```

```java
package com.bank.vending.model;

public class Slot {
    private final String slotId;
    private final Product product;
    private int quantity;

    public Slot(String slotId, Product product, int quantity) {
        this.slotId = slotId;
        this.product = product;
        this.quantity = quantity;
    }

    public boolean hasStock() { return quantity > 0; }

    public void dispense() {
        if (!hasStock()) throw new IllegalStateException(
                "Slot " + slotId + " is empty");
        quantity--;
    }

    public String getSlotId() { return slotId; }
    public Product getProduct() { return product; }
    public int getQuantity() { return quantity; }
}
```

### How does the State pattern drive the machine?

The `VendingMachine` holds a current state and delegates every action to it. Each state class permits only the transitions that make sense.

```java
package com.bank.vending.state;

import com.bank.vending.model.VendingMachine;
import java.math.BigDecimal;

public interface MachineState {
    void insertMoney(VendingMachine machine, BigDecimal amount);
    void selectProduct(VendingMachine machine, String slotId);
    void dispense(VendingMachine machine);
    void returnChange(VendingMachine machine);
}
```

```java
package com.bank.vending.state;

import com.bank.vending.model.VendingMachine;
import java.math.BigDecimal;

public class IdleState implements MachineState {
    @Override
    public void insertMoney(VendingMachine machine, BigDecimal amount) {
        machine.addBalance(amount);
        machine.setState(new SelectingState());
        System.out.println("Inserted " + amount
                + ", balance: " + machine.getBalance());
    }

    @Override
    public void selectProduct(VendingMachine machine, String slotId) {
        System.out.println("Insert money first");
    }

    @Override
    public void dispense(VendingMachine machine) {
        System.out.println("Insert money first");
    }

    @Override
    public void returnChange(VendingMachine machine) {
        System.out.println("No money to return");
    }
}
```

```java
package com.bank.vending.state;

import com.bank.vending.model.*;
import java.math.BigDecimal;

public class SelectingState implements MachineState {
    @Override
    public void insertMoney(VendingMachine machine, BigDecimal amount) {
        machine.addBalance(amount);
        System.out.println("Added " + amount
                + ", balance: " + machine.getBalance());
    }

    @Override
    public void selectProduct(VendingMachine machine, String slotId) {
        Slot slot = machine.getSlot(slotId);
        if (!slot.hasStock()) {
            System.out.println("Out of stock: " + slotId);
            return;
        }
        if (machine.getBalance().compareTo(
                slot.getProduct().getPrice()) < 0) {
            System.out.println("Insufficient funds. Need "
                    + slot.getProduct().getPrice()
                    + ", have " + machine.getBalance());
            return;
        }
        machine.setSelectedSlot(slot);
        machine.setState(new DispensingState());
        machine.dispense();
    }

    @Override
    public void dispense(VendingMachine machine) {
        System.out.println("Select a product first");
    }

    @Override
    public void returnChange(VendingMachine machine) {
        System.out.println("Returning " + machine.getBalance());
        machine.resetBalance();
        machine.setState(new IdleState());
    }
}
```

```java
package com.bank.vending.state;

import com.bank.vending.model.VendingMachine;
import java.math.BigDecimal;

public class DispensingState implements MachineState {
    @Override
    public void insertMoney(VendingMachine machine, BigDecimal amount) {
        System.out.println("Please wait, dispensing...");
    }

    @Override
    public void selectProduct(VendingMachine machine, String slotId) {
        System.out.println("Please wait, dispensing...");
    }

    @Override
    public void dispense(VendingMachine machine) {
        var slot = machine.getSelectedSlot();
        slot.dispense();
        BigDecimal price = slot.getProduct().getPrice();
        machine.subtractBalance(price);
        System.out.println("Dispensed: " + slot.getProduct().getName());
        machine.setState(new ReturningChangeState());
        machine.returnChange();
    }

    @Override
    public void returnChange(VendingMachine machine) {
        System.out.println("Please wait, dispensing...");
    }
}
```

### How does the VendingMachine context work?

```java
package com.bank.vending.model;

import com.bank.vending.state.*;
import java.math.BigDecimal;
import java.util.Map;

public class VendingMachine {
    private MachineState state;
    private BigDecimal balance;
    private final Map<String, Slot> slots;
    private Slot selectedSlot;

    public VendingMachine(Map<String, Slot> slots) {
        this.slots = slots;
        this.state = new IdleState();
        this.balance = BigDecimal.ZERO;
    }

    public void insertMoney(BigDecimal amount) {
        state.insertMoney(this, amount);
    }

    public void selectProduct(String slotId) {
        state.selectProduct(this, slotId);
    }

    public void dispense() { state.dispense(this); }
    public void returnChange() { state.returnChange(this); }

    public void setState(MachineState state) { this.state = state; }
    public BigDecimal getBalance() { return balance; }
    public void addBalance(BigDecimal amount) {
        balance = balance.add(amount);
    }
    public void subtractBalance(BigDecimal amount) {
        balance = balance.subtract(amount);
    }
    public void resetBalance() { balance = BigDecimal.ZERO; }
    public Slot getSlot(String id) { return slots.get(id); }
    public Slot getSelectedSlot() { return selectedSlot; }
    public void setSelectedSlot(Slot slot) { this.selectedSlot = slot; }
}
```

